#include <chrono>

#include <gtest/gtest.h>

#include "bench/scenario.hpp"

using namespace std::chrono_literals;

TEST(PhaseAt, EachPhaseStartsWhereTheLastOneEnds) {
  constexpr bench::Plan plan{.warmup = 2s, .drive = 3s, .settle = 3s};
  EXPECT_EQ(bench::phase_at(plan, 2s - 1ns), bench::Phase::warmup);
  EXPECT_EQ(bench::phase_at(plan, 2s), bench::Phase::drive);
  EXPECT_EQ(bench::phase_at(plan, 8s - 1ns), bench::Phase::settle);
  EXPECT_EQ(bench::phase_at(plan, 8s), bench::Phase::done);
}

#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <compare>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <ranges>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace bench {

// bench/time.hpp: a reading of a node's clock, in nanoseconds since that clock's zero.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

// bench/scenario.hpp from here on.

// One reading of the robot's own state, from the simulator's odometry. The time is the message's
// stamp, the moment the pose was true, and not the moment the message arrived.
struct Sample {
  Time at;
  double x_m = 0.0;
  double y_m = 0.0;
  double speed_mps = 0.0;  // forward speed, signed
};

// A scenario's timetable, in simulated time from the first odometry message of the run.
struct Plan {
  std::chrono::nanoseconds warmup;  // the world settles; no commands, and no samples are kept
  std::chrono::nanoseconds drive;   // the runner publishes the scenario's commands
  std::chrono::nanoseconds settle;  // no commands; the robot has to come to rest
};

enum class Phase { warmup, drive, settle, done };

[[nodiscard]] std::chrono::nanoseconds length(const Plan& plan) {
  return plan.warmup + plan.drive + plan.settle;
}

[[nodiscard]] Phase phase_at(const Plan& plan, std::chrono::nanoseconds since_start) {
  if (since_start < plan.warmup) return Phase::warmup;
  if (since_start < plan.warmup + plan.drive) return Phase::drive;
  if (since_start < length(plan)) return Phase::settle;
  return Phase::done;
}

// How a measured number is compared with its limit.
enum class Compare { at_least, at_most };

// One requirement of a scenario, with the number this run produced.
struct Check {
  std::string what;
  std::string unit;
  Compare compare;
  double limit;
  std::optional<double> measured;  // nothing when the run didn't produce the number
};

[[nodiscard]] bool met(const Check& check) {
  if (!check.measured) return false;
  return check.compare == Compare::at_least ? *check.measured >= check.limit : *check.measured <= check.limit;
}

// One run's verdict: it passed when every check is met.
struct Verdict {
  std::string scenario;
  std::int64_t samples;
  bool passed;
  std::vector<Check> checks;
};

[[nodiscard]] Verdict judge(std::string scenario, std::int64_t samples, std::vector<Check> checks) {
  const bool passed = std::ranges::all_of(checks, met);
  return {.scenario = std::move(scenario), .samples = samples, .passed = passed, .checks = std::move(checks)};
}

namespace {

[[nodiscard]] double seconds(std::chrono::nanoseconds d) { return std::chrono::duration<double>(d).count(); }

[[nodiscard]] std::string with_unit(double value, std::string_view unit) {
  return unit.empty() ? std::format("{:.2f}", value) : std::format("{:.2f} {}", value, unit);
}

[[nodiscard]] std::string line(const Check& check) {
  const std::string measured = check.measured ? with_unit(*check.measured, check.unit) : std::string("not measured");
  return std::format("{:<6} {}: {}, {} {}\n", met(check) ? "ok" : "failed", check.what, measured,
                     check.compare == Compare::at_least ? "at least" : "at most", with_unit(check.limit, check.unit));
}

}  // namespace

// The verdict file: "pass" or "fail" alone on the first line, then the run and its checks.
[[nodiscard]] std::string describe(const Verdict& verdict) {
  std::string text = std::format("{}\nscenario: {}\nsamples: {}\n", verdict.passed ? "pass" : "fail",
                                 verdict.scenario, verdict.samples);
  for (const Check& check : verdict.checks) text += line(check);
  return text;
}

// The straight line from the first sample to the last. Nothing when the run has no samples.
[[nodiscard]] std::optional<double> distance_from_start_m(std::span<const Sample> run) {
  if (run.empty()) return std::nullopt;
  return std::hypot(run.back().x_m - run.front().x_m, run.back().y_m - run.front().y_m);
}

[[nodiscard]] std::optional<double> top_speed_mps(std::span<const Sample> run) {
  if (run.empty()) return std::nullopt;
  return std::ranges::max(run | std::views::transform([](const Sample& s) { return std::abs(s.speed_mps); }));
}

// The time from which every later sample stayed within speed_limit_mps, when that stretch lasts
// at least for_at_least. Nothing when the robot still moved at the end, or came to rest too late.
[[nodiscard]] std::optional<Time> at_rest_since(std::span<const Sample> run, double speed_limit_mps,
                                                std::chrono::nanoseconds for_at_least) {
  if (run.empty()) return std::nullopt;
  auto backwards = run | std::views::reverse;
  const auto last_moving = std::ranges::find_if(
      backwards, [speed_limit_mps](const Sample& s) { return std::abs(s.speed_mps) > speed_limit_mps; });
  const auto first_at_rest = last_moving == std::ranges::end(backwards) ? run.begin() : last_moving.base();
  if (first_at_rest == run.end()) return std::nullopt;
  if (run.back().at.since_epoch - first_at_rest->at.since_epoch < for_at_least) return std::nullopt;
  return first_at_rest->at;
}

// What the smoke scenario requires, measured from one run. A later scenario writes its own list
// of checks over the same samples.
[[nodiscard]] std::vector<Check> smoke_checks(const Plan& plan, std::optional<std::chrono::nanoseconds> elapsed,
                                              std::span<const Sample> run, Time last_command) {
  using namespace std::chrono_literals;
  const std::optional<Time> rest = at_rest_since(run, 0.01, 300ms);
  const std::optional<double> to_rest =
      rest ? std::optional<double>(seconds(std::max(std::chrono::nanoseconds::zero(),
                                                    rest->since_epoch - last_command.since_epoch)))
           : std::nullopt;
  return {{.what = "simulated time from the first odometry message",
           .unit = "s",
           .compare = Compare::at_least,
           .limit = seconds(length(plan)),
           .measured = elapsed ? std::optional<double>(seconds(*elapsed)) : std::nullopt},
          {.what = "distance from the start",
           .unit = "m",
           .compare = Compare::at_least,
           .limit = 0.30,
           .measured = distance_from_start_m(run)},
          {.what = "top speed",
           .unit = "m/s",
           .compare = Compare::at_most,
           .limit = 0.30,
           .measured = top_speed_mps(run)},
          {.what = "time from the last command to rest",
           .unit = "s",
           .compare = Compare::at_most,
           .limit = 1.50,
           .measured = to_rest}};
}

}  // namespace bench

[[nodiscard]] constexpr std::string_view name(bench::Phase phase) {
  switch (phase) {
    case bench::Phase::warmup: return "warmup";
    case bench::Phase::drive: return "drive";
    case bench::Phase::settle: return "settle";
    case bench::Phase::done: return "done";
  }
  return "?";
}

// One odometry message of a made-up run, 100 ms of simulated time apart.
struct Moment {
  std::chrono::milliseconds t;
  double x_m;
  double speed_mps;
};

[[nodiscard]] std::vector<bench::Sample> samples(std::span<const Moment> moments) {
  std::vector<bench::Sample> run;
  for (const Moment& moment : moments) {
    run.push_back({.at = {moment.t}, .x_m = moment.x_m, .y_m = 0.0, .speed_mps = moment.speed_mps});
  }
  return run;
}

int main() {
  using namespace std::chrono_literals;
  constexpr bench::Plan smoke{.warmup = 2s, .drive = 3s, .settle = 3s};
  for (const auto t : {0s, 2s, 4s, 5s, 7s, 8s}) {
    std::cout << std::format("{} s into the run: {}\n", t.count(), name(bench::phase_at(smoke, t)));
  }
  std::cout << '\n';

  // A made-up run, one sample per 100 ms: the robot drives at 0.2 m/s, the last command goes out
  // at 1000 ms, the supervisor's stop follows 550 ms later, and the robot brakes at 1 m/s^2.
  constexpr std::array<Moment, 21> driven{{{.t = 0ms, .x_m = 0.000, .speed_mps = 0.00},
                                           {.t = 100ms, .x_m = 0.010, .speed_mps = 0.20},
                                           {.t = 200ms, .x_m = 0.030, .speed_mps = 0.20},
                                           {.t = 300ms, .x_m = 0.050, .speed_mps = 0.20},
                                           {.t = 400ms, .x_m = 0.070, .speed_mps = 0.20},
                                           {.t = 500ms, .x_m = 0.090, .speed_mps = 0.20},
                                           {.t = 600ms, .x_m = 0.110, .speed_mps = 0.20},
                                           {.t = 700ms, .x_m = 0.130, .speed_mps = 0.20},
                                           {.t = 800ms, .x_m = 0.150, .speed_mps = 0.20},
                                           {.t = 900ms, .x_m = 0.170, .speed_mps = 0.20},
                                           {.t = 1000ms, .x_m = 0.190, .speed_mps = 0.20},
                                           {.t = 1100ms, .x_m = 0.210, .speed_mps = 0.20},
                                           {.t = 1200ms, .x_m = 0.230, .speed_mps = 0.20},
                                           {.t = 1300ms, .x_m = 0.250, .speed_mps = 0.20},
                                           {.t = 1400ms, .x_m = 0.270, .speed_mps = 0.20},
                                           {.t = 1500ms, .x_m = 0.290, .speed_mps = 0.20},
                                           {.t = 1600ms, .x_m = 0.305, .speed_mps = 0.10},
                                           {.t = 1700ms, .x_m = 0.310, .speed_mps = 0.00},
                                           {.t = 1800ms, .x_m = 0.310, .speed_mps = 0.00},
                                           {.t = 1900ms, .x_m = 0.310, .speed_mps = 0.00},
                                           {.t = 2000ms, .x_m = 0.310, .speed_mps = 0.00}}};
  const bench::Time last_command{1000ms};
  const auto good = samples(driven);
  std::cout << bench::describe(
      bench::judge("smoke", std::ssize(good), bench::smoke_checks(smoke, 8s, good, last_command)));
  std::cout << '\n';

  // The same run with the relay stopped: the supervisor never opens the gate, so the robot stands
  // where it spawned from the first sample to the last.
  std::array<Moment, 21> held = driven;
  for (Moment& moment : held) {
    moment.x_m = 0.0;
    moment.speed_mps = 0.0;
  }
  const auto still = samples(held);
  std::cout << bench::describe(
      bench::judge("smoke", std::ssize(still), bench::smoke_checks(smoke, 8s, still, last_command)));
  std::cout << '\n';

  // The guard ended the run after 3 s of simulated time, with the robot still driving.
  const std::span<const bench::Sample> cut(good.data(), 11);
  std::cout << bench::describe(
      bench::judge("smoke", std::ssize(cut), bench::smoke_checks(smoke, 3s, cut, last_command)));
}

