namespace bench_nodes {

// The type the supervisor takes on /cmd_vel_nav.
using Command = geometry_msgs::msg::TwistStamped;

// Runs one scenario: it waits for the first odometry message, follows the plan on the simulation
// clock, judges the samples it kept, writes the verdict and ends the process.
class ScenarioRunner : public rclcpp::Node {
 public:
  explicit ScenarioRunner(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("scenario_runner", options),
        scenario_(declare_parameter<std::string>("scenario", "smoke")),
        verdict_file_(declare_parameter<std::string>("verdict_file", "")),
        speed_mps_(declare_parameter<double>("drive_speed_mps", 0.2)),
        plan_(declare_plan()) {
    const rclcpp::QoS qos(rclcpp::KeepLast(10));
    commands_ = create_publisher<Command>("cmd_vel_nav", qos);
    odometry_ = create_subscription<nav_msgs::msg::Odometry>(
        "odom_raw", qos, [this](const nav_msgs::msg::Odometry& msg) { on_odometry(msg); });
    timer_ = create_timer(std::chrono::milliseconds(50), [this] { on_tick(); });
    guard_ = create_wall_timer(std::chrono::seconds(declare_parameter<std::int64_t>("guard_s", 120)),
                               [this] { on_guard(); });
  }

  [[nodiscard]] const std::optional<bench::Verdict>& verdict() const { return verdict_; }

 private:
  [[nodiscard]] bench::Plan declare_plan() {
    return {.warmup = std::chrono::milliseconds(declare_parameter<std::int64_t>("warmup_ms", 2000)),
            .drive = std::chrono::milliseconds(declare_parameter<std::int64_t>("drive_ms", 3000)),
            .settle = std::chrono::milliseconds(declare_parameter<std::int64_t>("settle_ms", 3000))};
  }

  [[nodiscard]] bench::Time clock_time() const { return {std::chrono::nanoseconds(now().nanoseconds())}; }

  void on_odometry(const nav_msgs::msg::Odometry& message) {
    if (verdict_) return;
    const bench::Time at{std::chrono::nanoseconds(rclcpp::Time(message.header.stamp).nanoseconds())};
    if (!started_) {
      started_ = at;
      RCLCPP_INFO(get_logger(), "scenario %s starts at %.3f s of simulated time", scenario_.c_str(),
                  std::chrono::duration<double>(at.since_epoch).count());
      return;
    }
    if (at.since_epoch - started_->since_epoch < plan_.warmup) return;
    run_.push_back({.at = at,
                    .x_m = message.pose.pose.position.x,
                    .y_m = message.pose.pose.position.y,
                    .speed_mps = message.twist.twist.linear.x});
  }

  void on_tick() {
    if (!started_ || verdict_) return;
    const bench::Time now_time = clock_time();
    const bench::Phase phase = bench::phase_at(plan_, now_time.since_epoch - started_->since_epoch);
    if (phase == bench::Phase::drive) {
      Command command;
      command.header.stamp = now();
      command.header.frame_id = "base_link";
      command.twist.linear.x = speed_mps_;
      commands_->publish(command);
      last_command_ = now_time;
    } else if (phase == bench::Phase::done) {
      finish();
    }
  }

  // The guard runs on the wall clock, because a simulation that died stops simulated time.
  void on_guard() {
    RCLCPP_ERROR(get_logger(), "the guard ran out before the scenario reached the end of its plan");
    finish();
  }

  void finish() {
    if (verdict_) return;
    const std::optional<std::chrono::nanoseconds> elapsed =
        started_ ? std::optional<std::chrono::nanoseconds>(clock_time().since_epoch - started_->since_epoch)
                 : std::nullopt;
    verdict_ = bench::judge(scenario_, std::ssize(run_),
                            bench::smoke_checks(plan_, elapsed, run_, last_command_.value_or(bench::Time{})));
    const std::string text = bench::describe(*verdict_);
    RCLCPP_INFO(get_logger(), "%s", text.c_str());
    if (!verdict_file_.empty()) {
      std::ofstream file(verdict_file_);
      file << text;
      if (!file) RCLCPP_ERROR(get_logger(), "can't write %s", verdict_file_.c_str());
    }
    rclcpp::shutdown();
  }

  std::string scenario_;
  std::string verdict_file_;
  double speed_mps_;
  bench::Plan plan_;
  std::optional<bench::Time> started_;
  std::optional<bench::Time> last_command_;
  std::vector<bench::Sample> run_;
  std::optional<bench::Verdict> verdict_;
  rclcpp::Publisher<Command>::SharedPtr commands_;
  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odometry_;
  rclcpp::TimerBase::SharedPtr timer_;
  rclcpp::TimerBase::SharedPtr guard_;
};

}  // namespace bench_nodes

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  const auto runner = std::make_shared<bench_nodes::ScenarioRunner>();
  rclcpp::spin(runner);
  rclcpp::shutdown();
  const std::optional<bench::Verdict>& verdict = runner->verdict();
  return verdict && verdict->passed ? 0 : 1;
}
